def pair(n):
    """Return the first n items of the list for the pair.

    Args:
        n: Number of items.

    Returns:
        The first n items of the list for the pair.

    Examples:
        >>> pair([3, 4, 5, 7, 8])
        (4, 6)
        >>> pair([1, 2, 3, 4])
        (2, 3)
        >>> pair([1, 2, 3, 4])
        (2, 3)
    """
    for n1, n2 in n:
        if n1 < n2:
